/* @lc app=leetcode id=3594 lang=kotlin */ class Solution { fun minTime(n: Int, k: Int, m: Int, time: IntArray, mul: DoubleArray): Double = (1 shl n).let { F -> IntArray(F) { s -> (0 until n).filter { s shr it and 1 == 1 }.maxOfOrNull { time[it] } ?: 0 }.let { mt -> Array(F) { DoubleArray(m) { 1e18 } }.also { it[F - 1][0] = 0.0 }.let { dist -> java.util.PriorityQueue<DoubleArray>(compareBy<DoubleArray> { it[0] }).also { it.add(doubleArrayOf(0.0, (F - 1).toDouble(), 0.0)) }.let { pq -> DoubleArray(1) { 1e18 }.let { best -> generateSequence { pq.poll() }.filter { e -> e[0] <= dist[e[1].toInt()][e[2].toInt()] }.forEach { e -> e[0].let { dd -> e[1].toInt().let { mask -> e[2].toInt().let { st -> generateSequence(mask) { s -> if (s == 0) null else (s - 1) and mask }.filter { it != 0 && Integer.bitCount(it) <= k }.forEach { g -> (mt[g] * mul[st]).let { d -> ((st + Math.floor(d).toInt()) % m).let { ns -> (mask xor g).let { nm -> if (nm == 0) best.set(0, minOf(best[0], dd + d)) else ((F - 1) xor nm).let { far -> (0 until n).filter { far shr it and 1 == 1 }.distinctBy { time[it] }.forEach { r -> (time[r] * mul[ns]).let { rt -> ((ns + Math.floor(rt).toInt()) % m).let { ns2 -> (nm or (1 shl r)).let { m2 -> (dd + d + rt).let { nd -> if (nd < dist[m2][ns2]) pq.add(doubleArrayOf(nd, m2.toDouble(), ns2.toDouble())).also { dist[m2][ns2] = nd } } } } } } } } } } } } } } }.let { if (best[0] >= 1e17) -1.0 else best[0] } } } } } } }